def algorithm(func, dim, lb, ub, budget, rng):
    population_size = int(np.sqrt(budget))
    best_candidate = np.random.uniform(lb, ub, size=dim)
    current_best = func(best_candidate)

    for _ in range(population_size):
        candidate = np.clip(rng.normal(size=dim) * 0.5 + lb, lb, ub)
        if func(candidate) < current_best:
            current_best = func(candidate)
            best_candidate = candidate

    return best_candidate

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    x_best = rng.uniform(lb, ub, (1, dim))
    f_x_best = func(clip(x_best))

    for i in range(budget):
        sigma = 1.0
        x = np.zeros((1, dim))
        for j in range(dim):
            c = rng.normal(loc=0, scale=sigma)
            x[0, j] = x_best[0, j] + c

        f_x = func(clip(x))
        if f_x < f_x_best:
            f_x_best = f_x
            x_best = x.copy()

        sigma *= 0.99 ** (1 - i / budget)
    return clip(x_best)

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    best = np.zeros(dim)
    for _ in range(budget):
        x = rng.normal(size=dim)
        x = clip(x)
        f_x = func(x)

        if f_x < func(best):
            best = x

        # Local search refinement
        for i in range(dim):
            step_size = 0.1 * (ub - lb)
            new_x = best.copy()
            new_x[i] += rng.uniform(-step_size, step_size)
            new_x = clip(new_x)
            f_new_x = func(new_x)

            if f_new_x < f_x:
                x = new_x
                f_x = f_new_x

    return best
